#!/bin/bash
# verify_codebase_sync.sh - check that every path referenced in CODEBASE.md
# still exists in this repository.
#
# Why: CODEBASE.md is the map between architecture components and physical
# files. Renamed or deleted files silently rot that map, so CI-less work
# relies on this check after every structural change.
#
# Usage: scripts/verify_codebase_sync.sh   (run from anywhere)

set -u

cd "$(dirname "$0")/.." || exit 1

DOC="CODEBASE.md"

# Paths that only exist in other repositories (generated by the product).
EXCLUDE=" README.touched "

if [[ ! -f "$DOC" ]]; then
	echo "MISSING: $DOC"
	exit 1
fi

missing=0
checked=0

# Collect backtick spans, keep only path-like ones (contain a slash or end
# in a short extension), and test each against the filesystem.
while IFS= read -r span; do
	[[ "$span" =~ ^[.A-Za-z0-9][A-Za-z0-9._/-]*$ ]] || continue
	if [[ "$span" != */* && ! "$span" =~ \.[A-Za-z]{1,4}$ ]]; then
		continue
	fi
	case "$EXCLUDE" in *" $span "*) continue ;; esac
	checked=$((checked + 1))
	if [[ ! -e "${span%/}" ]]; then
		echo "MISSING: $span"
		missing=$((missing + 1))
	fi
done < <(grep -oE '`[^`]+`' "$DOC" | tr -d '`' | sort -u)

echo "Checked $checked path references, $missing missing."
if [[ $missing -gt 0 ]]; then
	exit 1
fi
exit 0
